// Format error output for console
const error = $node["Parse Error Message"].json.error;
const timestamp = new Date($node["Parse Error Message"].json.timestamp).toLocaleString();
const bodyPreview = $node["Parse Error Message"].json.body.substring(0, 100);

const errorMessage = `[${timestamp}] ERROR: ${error}\nBody: ${bodyPreview}...`;

console.error('🔴 ERROR:', errorMessage);

return {
  logged: true,
  error: error,
  message: errorMessage
};
